def esc(s): return html.escape(s,quote=True)
def btn(label,cat,cls=''):return f'<button class="{cls}" data-cat="{cat}" type="button"><span aria-hidden="true">{SYMS[cat]}</span><span>{label}</span></button>'
def category_buttons(cls):return ''.join(btn(c,c,cls) for c in CATS)
def shell(n):
    if n==0:return f'''<header class="brand"><span class="overline">A tool chest for your internet</span><h1>ILUD<span>IST</span></h1><div class="brand-actions"><button class="sound-toggle" aria-label="Enable interface sounds" aria-pressed="false">♪</button><button class="icon-button search-trigger" aria-label="Search fixes">⌕</button></div></header><div class="lamp" aria-hidden="true"></div><section class="cabinet"><p class="intro">Pick a tool for a cleaner internet.</p><nav class="tool-shelf" aria-label="Browse by task">{category_buttons('tool')}</nav><div class="drawer"><div class="drawer-head"><span>OPEN DRAWER</span><button class="saved-trigger">Saved <span class="saved-count">0</span></button></div><div id="results" class="results"></div></div></section>'''
    if n==1:return f'''<header class="brand"><button class="icon-button search-trigger" aria-label="Search fixes">☰</button><h1>ILUD<span>IST</span></h1><button class="saved-trigger icon-button" aria-label="Saved fixes">◇<span class="saved-count">0</span></button></header><main class="sanctuary"><span class="star">✦</span><h2>What is bothering you?</h2><nav class="questions" aria-label="Choose a concern"><button data-intent="answering">AI answering for me</button><button data-intent="recommending">AI deciding what I see</button><button data-intent="generating">Generated content everywhere</button></nav><p class="path-label">Choose where it happens</p><nav class="chapel-cats" aria-label="Browse by task">{category_buttons('chapel-cat')}</nav><section class="altar"><span class="overline">A way forward</span><div id="results" class="results"></div></section></main>'''
