    if n==3:return f'''<header class="brand"><h1>ILUD<span>IST</span></h1><div class="brand-actions"><button class="sound-toggle" aria-label="Enable interface sounds" aria-pressed="false">♪</button><button class="search-trigger icon-button" aria-label="Search fixes">⌕</button></div></header><main class="instrument"><p class="overline">A small instrument for choosing less</p><h2>What do you want less of?</h2><div class="dial-wrap"><div class="dial-pointer" aria-hidden="true">◆</div><div class="dial-wheel" id="dial-wheel" role="group" aria-label="Task dial">{''.join(btn(c,c,'dial-sector') for c in CATS)}</div><div class="dial-hub" aria-hidden="true">TURN<br>TO<br>CHOOSE</div></div><p class="dial-help">Tap a segment or drag the dial. Arrow keys move one stop.</p><section class="instrument-panel"><span class="overline">Selected · <span class="current-cat">Search</span></span><div id="results" class="results"></div></section><button class="saved-trigger footer-button">Saved fixes <span class="saved-count">0</span></button></main>'''
