    if n==8:return f'''<header class="brand"><h1>ILUD<span>IST</span></h1><button class="saved-trigger icon-button" aria-label="Saved places">◇<span class="saved-count">0</span></button></header><main class="atlas"><div class="map-heading"><span class="overline">The atlas of a quieter internet</span><h2>Choose an island.</h2><button class="search-trigger">Search the atlas ⌕</button></div><nav class="islands" aria-label="Explore a task">{''.join(btn(c,c,'island island-'+str(i)) for i,c in enumerate(CATS))}<div class="compass" aria-hidden="true">✦<small>N</small></div></nav><section class="island-guide"><span class="overline">Field notes / <span class="current-cat">Search</span></span><div id="results" class="results"></div></section></main>'''
    return f'''<header class="brand"><h1>ILUD<span>IST</span></h1><div class="brand-actions"><button class="sound-toggle" aria-label="Enable interface sounds" aria-pressed="false">♪</button><button class="search-trigger icon-button" aria-label="Search the folio">✦</button></div></header><main class="folio"><div class="binder-top"><span>ILUDIST / TOOLS FOR A CLEARER INTERNET</span><button class="saved-trigger">Saved <span class="saved-count">0</span></button></div><div class="paper-stack" id="paper-stack"><div class="paper-back back-one"></div><div class="paper-back back-two"></div><section class="paper-front"><span class="overline">FILE <span class="file-number">01</span> / <span class="current-cat">Search</span></span><div id="results" class="results"></div><div class="swipe-hint">Swipe the paper or use the tabs to change the file.</div></section></div><nav class="binder-tabs" aria-label="Choose a file">{category_buttons('binder-tab')}</nav></main>'''

